#!/usr/bin/env bash
# Translate the MAVLink C library of the reference build (README.md, "Phase 4: the MAVLink C library"):
# ArduPilot's MAVLink fork e03dad40 generated by the reference build for dialect `all`
# (build/reference/ap/build/sitl/libraries/GCS_MAVLink/include/mavlink/v2.0/), configured by
# GCS_MAVLink.h (MAVLINK_SEPARATE_HELPERS, MAVLINK_USE_CONVENIENCE_FUNCTIONS, MAVLINK_SEND_UART_BYTES =
# comm_send_buffer, MAVLINK_GET_CHANNEL_BUFFER/STATUS, 16 channels, aligned fields, little endian), with the
# reference build's flags of GCS_MAVLink.cpp's unit: ardupilot/unity_mavlink.cpp (written by
# ardupilot/gen_unity_mavlink.py) -> ardupilot/out/Mavlink/Mavlink_lib.lean.
# The generated headers are --lib-dir (translated as far as the test functions use them); the unity's
# file-scope state (the channel buffers and status, mavlink_system, the UART byte queue) is threaded through
# the functions that reach it (--mavlink); `mavlink_status_t::signing` and `signing_streams` are always null
# (AP_MAVLINK_SIGNING_ENABLED 0: nothing assigns them) and folded (--null-member); comm_send_lock/unlock (the
# channel semaphore and the txspace check of GCS_MAVLink.cpp:192-215) are left out (--drop: one thread, the
# byte queue never fills in the tests). Also checks the unity (check_unity.py against GCS_MAVLink.cpp's unit)
# and every record layout the translation uses against clang's (ardupilot/check_layouts.py).
# Usage: ardupilot/translate_mavlink.sh [extra cpp2lean options]
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$HERE/.." && pwd)"
. "$HERE/ekf_common.sh"
OUT="${MAVLINK_OUT:-$ROOT/ardupilot/out/Mavlink}"
MAV="$REF/build/sitl/libraries/GCS_MAVLink/include/mavlink/v2.0"
ekf_flags GCS_MAVLink/GCS_MAVLink.cpp
# the MAVLink headers and GCS_MAVLink.h preprocess in the unity exactly as in GCS_MAVLink.cpp's own unit
HDRS=("$RL/GCS_MAVLink/GCS_MAVLink.h" "$MAV/mavlink_helpers.h" "$MAV/protocol.h" "$MAV/mavlink_types.h" "$MAV/checksum.h" "$MAV/all/all.h")
while read -r h; do HDRS+=("$MAV/$h"); done < <(sed -n 's|^// ---- [A-Z0-9_]* (\(.*\.h\)) ----$|\1|p' "$HERE/unity_mavlink.cpp")
CHECK=(python3 "$HERE/check_unity.py" "$HERE/unity_mavlink.cpp" --normalize --home="$RL/GCS_MAVLink/GCS_MAVLink.cpp" "${HDRS[@]}" -- "${EKF_FLAGS[@]}")
"${CHECK[@]}" > /dev/null || { "${CHECK[@]}" | grep -v "the same"; exit 1; }
cd "$ROOT"
python3 cpp2lean.py "$HERE/unity_mavlink.cpp" -o "$OUT" --namespace Mavlink_lib --nest --lib-dir "$REF/build/sitl/libraries/GCS_MAVLink/include" \
  --pointer-params --runtime-loops --c-strings --byte-objects --general-loops \
  --mavlink --null-member __mavlink_status::signing,__mavlink_status::signing_streams \
  --drop comm_send_lock --drop comm_send_unlock \
  --src-root "$RL" "${EKF_CA[@]}" "$@"
python3 "$HERE/check_layouts.py" "$OUT/Mavlink_lib.signatures.json" -- "${EKF_FLAGS[@]}"
